module TopModule (
    input  logic [3:0] x,
    output logic       f
);

always_comb begin
    unique case (x)
        4'b0000: f = 1'b1;
        4'b0001: f = 1'b1;
        4'b0010: f = 1'b0;
        4'b0011: f = 1'b0;
        4'b0100: f = 1'b1;
        4'b0101: f = 1'b1;
        4'b0110: f = 1'b1;
        4'b0111: f = 1'b0;
        4'b1000: f = 1'b0;
        4'b1001: f = 1'b0;
        4'b1010: f = 1'b0;
        4'b1011: f = 1'b0;
        4'b1100: f = 1'b1;
        4'b1101: f = 1'b0;
        4'b1110: f = 1'b1;
        4'b1111: f = 1'b1;
        default: f = 1'b0;
    endcase
end

endmodule

module tb_TopModule;

    logic [3:0] x;
    logic       f;

    TopModule uut (
        .x(x),
        .f(f)
    );

    // Independent golden model function
    function logic golden_f(input [3:0] val);
        case (val)
            4'b0000: golden_f = 1'b1;
            4'b0001: golden_f = 1'b1;
            4'b0010: golden_f = 1'b0;
            4'b0011: golden_f = 1'b0;
            4'b0100: golden_f = 1'b1;
            4'b0101: golden_f = 1'b1;
            4'b0110: golden_f = 1'b1;
            4'b0111: golden_f = 1'b0;
            4'b1000: golden_f = 1'b0;
            4'b1001: golden_f = 1'b0;
            4'b1010: golden_f = 1'b0;
            4'b1011: golden_f = 1'b0;
            4'b1100: golden_f = 1'b1;
            4'b1101: golden_f = 1'b0;
            4'b1110: golden_f = 1'b1;
            4'b1111: golden_f = 1'b1;
            default: golden_f = 1'b0;
        endcase
    endfunction

    initial begin
        integer i;
        for (i = 0; i < 16; i = i + 1) begin
            x = i[3:0];
            #10;
            if (f !== golden_f(x)) begin
                $display("SELFFAIL: x = %b (val %0d), expected %b, got %b", x, i, golden_f(x), f);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
